async function getLatestVersion() {
  try {
    const response = await fetch('https://api.github.com/repos/jerryzmtz/tauritavern-preset-manager/tags');
    const tags = await response.json();
    return tags[0]?.name || 'main';
  } catch {
    return 'main';
  }
}

const version = await getLatestVersion();
await import(`https://testingcf.jsdelivr.net/gh/jerryzmtz/tauritavern-preset-manager@${version}/dist/preset-manager/index.js`);
